def git_blob(data):
    return hashlib.sha1(b"blob " + str(len(data)).encode() + b"\0" + data).hexdigest()

def write_json(path, value):
    path.write_text(json.dumps(value, ensure_ascii=False, sort_keys=True, indent=2) + "\n")
    path.chmod(0o600)

def main():
    args = argparse.ArgumentParser()
    args.add_argument("--output", required=True, help="New private directory for exact source and retained workspaces")
    a = args.parse_args()
    out = Path(a.output).absolute()
    out.mkdir(mode=0o700, parents=True, exist_ok=False)
    source = out / "source"; source.mkdir(mode=0o700)
    for relative, content in SOURCE_TEXT.items():
        data = content.encode("utf-8")
        assert git_blob(data) == SOURCE_MANIFEST[relative], "Embedded source blob differs: " + relative
        path = source / relative; path.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
        path.write_bytes(data); path.chmod(0o600)
    write_json(out / "source-manifest.json", {"commit": SOURCE_COMMIT, "gitBlobs": SOURCE_MANIFEST})
    sys.path.insert(0, str(source / "feeds"))
    from feed_workspace import FeedWorkspace, DEFAULT_FIELDS
    from original import digest
    from server import OperatorServer
    from operations import execute
    from opml_source import parse_opml
    import feed_workspace
    node = os.environ.get("SF30_XML_NODE") or shutil.which("node")
    assert node, "An existing Node runtime is required"
    os.environ["SF30_XML_NODE"] = node
    result = {"operationId":"SCF-FEED-COLLECTION-NATIVE-8F43-20261012",
              "sourceCommit":SOURCE_COMMIT,"startedAt":time.strftime("%Y-%m-%dT%H:%M:%SZ",time.gmtime()),
              "runtime":{"python":sys.version.split()[0],"node":subprocess.check_output([node,"--version"],text=True).strip(),
                         "platform":platform.platform()},"completed":[]}
    def checkpoint(stage, **values):
        result.update(values); result["completed"].append(stage)
        write_json(out/"journey-result.json",result)
        print(json.dumps({"stage":stage,**values},sort_keys=True),flush=True)
    ws = received = http = console = None
    request_log = []
    calls = collections.Counter()
    class FeedSource(BaseHTTPRequestHandler):
        def log_message(self,*unused): pass
        def do_GET(self):
            calls[self.path] += 1
            tag = '"collection-'+self.path.strip("/")+'-v1"'
            if self.path == "/rss" and calls[self.path] == 1:
                body,status,media=b"temporarily unavailable",503,"text/plain"
            elif self.headers.get("If-None-Match") == tag:
                body,status,media=b"",304,"application/xml"
            elif self.path == "/atom":
                body,status,media=atom,200,"application/atom+xml"
            elif self.path == "/rss":
                body,status,media=rss,200,"application/rss+xml"
            else:
                body,status,media=b"unexpected source",404,"text/plain"
            request_log.append({"path":self.path,"status":status,"ifNoneMatch":self.headers.get("If-None-Match")})
            self.send_response(status); self.send_header("Content-Type",media)
            self.send_header("Content-Length",str(len(body))); self.send_header("ETag",tag)
            if status==503: self.send_header("Retry-After","0")
            self.end_headers(); self.wfile.write(body)
    try:
        ws = FeedWorkspace(out/"seller",create=True)
        public_bytes=(source/"inputs/newsblur-subscriptions.opml").read_bytes()
        public=ws.subscriptions.import_opml(public_bytes,"import-public-newsblur")
        assert public["head"]["title"] == "Ben Werdmuller's NewsBlur subscriptions"
        assert ws.subscriptions.source_path(public["sourceId"]).read_bytes() == public_bytes
        assert any(x["folders"] for x in public["entries"])
        checkpoint("original-public-opml",publicOPML={"gitBlob":SOURCE_MANIFEST["inputs/newsblur-subscriptions.opml"],
            "sha256":public["sourceId"],"bytes":len(public_bytes),"subscriptions":len(public["entries"]),
            "outlines":public["outlineCount"],"topFolders":[x["attributes"]["text"] for x in public["tree"]]})
        http=ThreadingHTTPServer(("127.0.0.1",0),FeedSource)
        origin=f"http://127.0.0.1:{http.server_port}"
        atom=('<?xml version="1.0"?><feed xmlns="http://www.w3.org/2005/Atom">'
              '<id>urn:collection:atom</id><title>Research</title><updated>2026-10-12T00:00:00Z</updated>'
              '<author><name>Original author</name></author><entry><id>urn:collection:item:1</id>'
              '<title>Retained observation</title><updated>2026-10-12T00:00:00Z</updated>'
              '<summary>Original Atom source</summary></entry></feed>').encode()
        rss=('<?xml version="1.0"?><rss version="2.0"><channel><title>Operations</title>'
             '<link>https://example.org/operations</link><description>Original RSS source</description>'
             '<item><guid isPermaLink="false">collection-rss-one</guid><title>Service update</title>'
             '<description>Retained after retry</description></item></channel></rss>').encode()
        threading.Thread(target=http.serve_forever,daemon=True).start()
        opml=('<?xml version="1.0"?><opml version="2.0"><head><title>Selected research library</title></head><body>'
              f'<outline text="Research"><outline text="Atom" type="RSS" xmlUrl="{origin}/atom"/>'
              f'<outline text="Archive"><outline text="Same source" type="rss" xmlUrl="{origin}/atom"/></outline></outline>'
              f'<outline text="Operations"><outline text="RSS" type="rss" xmlUrl="{origin}/rss"/></outline>'
              f'<outline text="Paused" isComment="true"><outline text="Later" type="rss" xmlUrl="{origin}/disabled"/></outline>'
              '<outline text="Retained include" type="include" url="https://example.org/list.opml"/></body></opml>').encode()
        doc=ws.subscriptions.import_opml(opml,"import-selected-library")
        plan=ws.subscriptions.plan(doc["sourceId"]); members=[]
        for entry in plan["entries"]:
            feed_id={"atom":"feed-a","rss":"feed-b","disabled":"feed-c"}[entry["url"].rsplit("/",1)[1]]
            members.append({"sourceId":doc["sourceId"],"entryId":entry["entryId"],"feedId":feed_id,
                            "enabled":feed_id!="feed-c"})
        configs={fid:{"url":origin+"/"+path,"label":label,"rssIdentity":"guid",
                      "allowedOrigins":[origin]} for fid,path,label in
                 [("feed-a","atom","Research"),("feed-b","rss","Operations"),("feed-c","disabled","Paused source")]}
        save={"action":"collection-save","collectionId":"research-library","title":"Research library",
              "members":members,"newFeeds":configs,"expectedRevision":0,"operationId":"save-selection-a"}
        original_register=ws.register
        intercepted=[]
        def interrupted_register(*argv,**kw):
            value=original_register(*argv,**kw); intercepted.append(argv[0])
            if len(intercepted)==1: raise InterruptedError("Native journey interruption after the original child completed")
            return value
        ws.register=interrupted_register
        try:
            execute(ws,save)
            raise AssertionError("The chosen child interruption did not occur")
        except InterruptedError: pass
        finally: ws.register=original_register
        assert len(ws.feed_state()["feeds"])==1
        ws.close(); ws=FeedWorkspace(out/"seller")
        selected=execute(ws,save)
        assert execute(ws,save)==selected and selected["revision"]==1
        assert len(selected["members"])==4 and len(ws.feed_state()["feeds"])==3
        revisions={f:ws.feed(f)["revision"] for f in ("feed-a","feed-b")}
        run=ws.subscriptions.capture("research-library",1,revisions,"acquire-selection-a")
        assert run["state"]=="PARTIAL"
        assert [x["state"] for x in run["items"]]==["CAPTURED","FAILED"]
        ws.close(); ws=FeedWorkspace(out/"seller")
        run=ws.subscriptions.resume(run["id"])
        assert run["state"]=="CAPTURED" and calls["/atom"]==1 and calls["/rss"]==2
        assert ws.subscriptions.resume(run["id"])["id"]==run["id"]
        for item in ws.subscriptions.review(run["id"])["items"]:
            assert not item["feedIdentityChanged"]
            ws.apply(item["captureId"],ws.feed(item["feedId"])["revision"],"apply-a-"+item["feedId"])
        revisions={f:ws.feed(f)["revision"] for f in ("feed-a","feed-b")}
        first=ws.subscriptions.edition(run["id"],"Research library edition",DEFAULT_FIELDS,revisions,"edition-selection-a")
        assert first["edition"]["rowCount"]==2
        record=ws.records("feed-a")["items"][0]
        ws.annotate("feed-a",record["identity"],0,"note-research-one",note="Retained operator note",tags=["research"],starred=True)
        checkpoint("partial-acquisition-reopen",runId=run["id"],requests=list(request_log),
                   registrationRecovery=intercepted,distinctAcquiredFeeds=2,editionA=first["edition"]["id"])
        second_selection=ws.subscriptions.save("research-library","Research library revised",members,{},1,"save-selection-b")
        run2=ws.subscriptions.capture("research-library",2,revisions,"acquire-selection-b")
        assert run2["state"]=="CAPTURED" and [r["status"] for r in request_log[-2:]]==[304,304]
        for item in run2["items"]:
            ws.apply(item["captureId"],ws.feed(item["feedId"])["revision"],"apply-b-"+item["feedId"])
        revisions2={f:ws.feed(f)["revision"] for f in ("feed-a","feed-b")}
        edition=ws.subscriptions.edition(run2["id"],"Research library edition",DEFAULT_FIELDS,revisions2,"edition-selection-b")
        comparison=ws.compare(first["edition"]["buildId"],edition["edition"]["buildId"])
        query=ws.query(edition["edition"]["buildId"],{"limit":"1"})
        assert query["response"]["status"]==200
        page=query["response"]["body"]
        assert page["page"]["total"]==2 and page["page"]["returned"]==1 and page["page"]["nextCursor"]
        tail=ws.query(edition["edition"]["buildId"],{"limit":"1","cursor":page["page"]["nextCursor"]})
        assert tail["response"]["body"]["page"]["returned"]==1
        generated=ws.subscriptions.opml("research-library")
        selected_doc=parse_opml(generated,feed_workspace.validate_url)
        assert len(selected_doc["entries"])==3 and selected_doc["entries"][1]["folders"]==["Research","Archive"]
        packet=ws.subscriptions.export(edition["binding"]["id"],out/"research-library.zip")
        checkpoint("native-selected-edition",editionB=edition["edition"]["id"],bindingId=edition["binding"]["id"],
                   snapshot=query["dataset"]["snapshot"],engineBlob=query["engineBlob"],rows=2,
                   comparison=comparison,packetSha256=packet["sha256"],packetBytes=packet["bytes"])
        ws.close(); ws=None
        received=FeedWorkspace(out/"customer",create=True)
        reopened=received.subscriptions.receive(out/"research-library.zip","receive-research-library")
        assert received.subscriptions.receive(out/"research-library.zip","receive-research-library")==reopened
        assert received.subscriptions.resume(run2["id"])["id"]==run2["id"]
        assert received.subscriptions.source_path(doc["sourceId"]).read_bytes()==opml
        assert received.subscriptions.opml("research-library")==generated
        actual=received.query(edition["edition"]["buildId"],{})
        assert actual["dataset"]["snapshot"]==query["dataset"]["snapshot"] and actual["response"]["body"]["page"]["total"]==2
        assert received.records("feed-a")["items"][0]["review"]["note"]=="Retained operator note"
        view=received.subscriptions.view("research-library")
        assert set(view["missingRegistrations"])=={"feed-c"}
        assert view["missingRegistrations"]["feed-c"]==selected["feeds"][2]["config"]
        enabled=[m|{"enabled":True} if m["feedId"]=="feed-c" else m for m in members]
        restored=received.subscriptions.save("research-library","Research library restored",enabled,
                                             view["missingRegistrations"],2,"restore-retained-subscription")
        assert restored["revision"]==3 and not received.subscriptions.view("research-library")["missingRegistrations"]
        console=OperatorServer(received)
        threading.Thread(target=console.serve_forever,daemon=True).start()
        def get(path,authenticated=True):
            headers={"Authorization":"Bearer "+console.token} if authenticated else {}
            with urlopen(Request(console.origin+path,headers=headers),timeout=30) as response:
                return response.status,response.read()
        status,html=get("/subscriptions",False)
        assert status==200 and b"subscriptions.js" in html
        status,data=get("/api/subscriptions/collection?id=research-library")
        assert status==200 and json.loads(data)["collection"]["revision"]==3
        status,returned=get("/api/subscriptions/original?source="+doc["sourceId"])
        assert returned==opml
        console.shutdown(); console.server_close(); console.join_worker(); console=None
        received.close(); received=None
        cli=subprocess.run([node,str(source/"feeds/cli.mjs"),"--workspace",str(out/"customer"),
                            "subscriptions","show","--collection","research-library"],
                           text=True,capture_output=True,timeout=60,
                           env=dict(os.environ,SF30_FEED_PYTHON=sys.executable))
        assert cli.returncode==0,cli.stderr
        assert json.loads(cli.stdout)["collection"]["revision"]==3
        assert calls["/disabled"]==0
        checkpoint("portable-customer-console-cli",receivedEdition=reopened["editionId"],receivedRun=reopened["runId"],
                   restoredDisabledRegistration="feed-c",customerCollectionRevision=3,
                   originalOPMLSha256=digest(opml),sourceRequests=list(request_log),
                   consoleHTTP=200,originalCLIExit=cli.returncode)
        result["state"]="COMPLETED"
        result["completedAt"]=time.strftime("%Y-%m-%dT%H:%M:%SZ",time.gmtime())
    except BaseException as error:
        result["state"]="FAILED"; result["error"]=str(error); result["traceback"]=traceback.format_exc()
        raise
    finally:
        if console:
            console.shutdown(); console.server_close(); console.join_worker()
        if received: received.close()
        if ws: ws.close()
        if http: http.shutdown(); http.server_close()
        write_json(out/"journey-result.json",result)
        print(json.dumps(result,sort_keys=True),flush=True)

if __name__=="__main__":
    main()
